// Macro: Send Image Dialog (via joes-pf2e-stuff API)
(async () => {
	const mod = game.modules.get("joes-pf2e-stuff");
	if (!mod?.active) return ui.notifications.error("joes-pf2e-stuff is not active.");
	const api = mod.api;
	if (!api?.sendImageDialog) return ui.notifications.error("sendImageDialog() is not exposed on the module API.");

	// Call your function with whatever options it expects.
	// Replace values below to match your implementation/signature.
	await api.sendImageDialog({
		src: "assets/images/start-the-timer.webp",
		title: "Show Overlay",
		broadcast: true,   // true = send to all players (if your function supports it)
		opacity: 0.9,      // example option
		closeOnRefresh: false // example option
	});
})();
